patch:
diff --git a/repro/windows-cross-drive.js b/repro/windows-cross-drive.js
new file mode 100644
index 0000000..dcdb95e
--- /dev/null
+++ b/repro/windows-cross-drive.js
@@ -0,0 +1,58 @@
+/**
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ *
+ * Simulates Windows path semantics on any OS: every `require("path")` /
+ * `require("node:path")` returns `path.win32`, and the cwd is `C:\Project`.
+ * Run: node repro/windows-cross-drive.js
+ */
+"use strict";
+
+const Module = require("node:module");
+const path = require("node:path");
+
+const originalLoad = Module._load;
+
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return path.win32;
+    }
+    return originalLoad.call(this, request, ...rest);
+};
+const CWD = "C:\\Project";
+
+process.cwd = () => CWD;
+
+const { Linter, ESLint } = require("../lib/api");
+
+const cases = [
+    ["C:\\Project\\foo.js", "inside cwd -> linted"],
+    ["C:\\other\\foo.js", "same drive, outside cwd -> ignored"],
+    ["F:\\foo.js", "different drive -> should be ignored"]
+];
+
+(async () => {
+    let bug = false;
+
+    for (const [file, expectation] of cases) {
+        const rel = path.win32.relative(CWD, file);
+        const linter = new Linter({ configType: "flat", cwd: CWD });
+        const linterMsgs = linter.verify("foo()", { rules: { "no-undef": "error" } }, file);
+
+        const eslint = new ESLint({ cwd: CWD, overrideConfigFile: true, overrideConfig: { rules: { "no-undef": "error" } } });
+        const [result] = await eslint.lintText("foo();\n", { filePath: file, warnIgnored: true });
+        const ignored = await eslint.isPathIgnored(file);
+
+        console.log(`\n${file}  (${expectation})`);
+        console.log(`  path.win32.relative(cwd, file) = ${JSON.stringify(rel)}`);
+        console.log(`  Linter#verify:      ${linterMsgs.map(m => `${m.ruleId ?? "(none)"}: ${m.message}`).join(" | ") || "(no messages)"}`);
+        console.log(`  ESLint#lintText:    ${result.messages.map(m => `${m.ruleId ?? "(none)"}: ${m.message}`).join(" | ") || "(no messages)"}`);
+        console.log(`  ESLint#isPathIgnored: ${ignored}`);
+
+        if (file.startsWith("F:") && (!ignored || linterMsgs.some(m => m.ruleId === "no-undef"))) {
+            bug = true;
+        }
+    }
+
+    console.log(bug ? "\nBUG REPRODUCED: F:\\foo.js (different drive) is linted instead of ignored." : "\nNot reproduced.");
+    process.exitCode = bug ? 1 : 0;
+})();
